#!/usr/bin/env node
import { runCLI } from '../src/cli.js';

process.on('unhandledRejection', (err) => {
  console.error(`\nUnexpected error: ${err?.stack || err}`);
  process.exitCode = 1;
});

runCLI(process.argv.slice(2));

import fs from 'node:fs';
import path from 'node:path';
import readline from 'node:readline';
import { Agent } from './agent.js';
import { SessionStore } from './session.js';
import {
  loadConfig,
  saveConfig,
  readRawConfig,
  resolveProviderModel,
} from './config.js';
import { PROVIDERS, providerIds, providerTable } from './providers/index.js';
import { VERSION, DEFAULT_CONFIG } from './constants.js';
import { homeDir, ensureHome, fmtTokens, truncate } from './util.js';
import { createStreamRenderer } from './md.js';

/* ------------------------------------------------------------------ */
/* Terminal helpers                                                    */
/* ------------------------------------------------------------------ */

const useColor = process.stdout.isTTY && !process.env.NO_COLOR;
const C = (code, s) => (useColor ? `\x1b[${code}m${s}\x1b[0m` : s);
const dim = (s) => C('2', s);
const cyan = (s) => C('36', s);
const green = (s) => C('32', s);
const red = (s) => C('31', s);
const yellow = (s) => C('33', s);
const bold = (s) => C('1', s);
const italic = (s) => C('3', s);

const SPIN_FRAMES = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];

function startSpinner(label) {
  if (!process.stdout.isTTY) return null;
  let i = 0;
  process.stdout.write('\x1b[?25l');
  const id = setInterval(() => {
    process.stdout.write(`\r${dim(SPIN_FRAMES[i % SPIN_FRAMES.length])} ${dim(label)}`);
    i++;
  }, 80);
  return { id, stopped: false };
}

function stopSpinner(sp) {
  if (!sp || sp.stopped) return;
  sp.stopped = true;
  clearInterval(sp.id);
  process.stdout.write('\r\x1b[K');
  process.stdout.write('\x1b[?25h');
}

/* ------------------------------------------------------------------ */
/* Main dispatch                                                       */
/* ------------------------------------------------------------------ */

export async function runCLI(argv) {
  const [cmd, ...rest] = argv;

  if (cmd === 'configure') return configure();
  if (cmd === 'serve') {
    const { startServer } = await import('./server.js');
    const config = loadConfig({});
    const port = flagValue(rest, ['-p', '--port']) || config.port;
    return startServer({ config, port });
  }
  if (cmd === 'ask' || cmd === 'chat') return ask(rest);
  if (cmd === 'sessions' || cmd === 'list' || cmd === 'ls') return listSessions();
  if (cmd === 'use') return useSession(rest);
  if (cmd === 'new') return newSession(rest);
  if (cmd === 'rm' || cmd === 'remove' || cmd === 'delete') return removeSession(rest);
  if (cmd === 'rename') return renameSession(rest);
  if (cmd === 'providers' || cmd === 'models') return printProviders();
  if (cmd === 'system') return setSystemConfig(rest);
  if (cmd === 'status') return printStatus();
  if (cmd === 'env') return printEnv();
  if (cmd === 'version' || cmd === '-v' || cmd === '--version') {
    console.log(`alphaa ${VERSION}`);
    return;
  }
  if (cmd === 'help' || cmd === '--help' || cmd === '-h') {
    printHelp();
    return;
  }

  // No subcommand (or only flags): piped stdin → one-shot ask; TTY → REPL
  if (!cmd || cmd.startsWith('-')) {
    if (!process.stdin.isTTY) {
      const input = await readStdin();
      if (input.trim()) return ask(argv.length ? [...argv, input.trim()] : [input.trim()]);
      printHelp();
      return;
    }
    return cmd ? repl(argv) : repl();
  }

  // Unknown subcommand → show a hint
  console.error(red(`Unknown command "${cmd}". Run \`alphaa help\` for usage.`));
  process.exitCode = 1;
  return;
}

function readStdin() {
  return new Promise((resolve) => {
    let data = '';
    process.stdin.setEncoding('utf8');
    process.stdin.on('data', (chunk) => {
      data += chunk;
    });
    process.stdin.on('end', () => resolve(data));
  });
}

function flagValue(args, names) {
  for (let i = 0; i < args.length; i++) {
    if (names.includes(args[i]) && args[i + 1]) return args[i + 1];
  }
  return undefined;
}

function flagBool(args, names) {
  return args.some((a) => names.includes(a));
}

const VALUE_FLAGS = new Set(['-p', '--provider', '-m', '--model', '-s', '--session']);

/** Return the positional args, dropping known flags together with their values. */
export function stripFlags(args) {
  const out = [];
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a.startsWith('-')) {
      if (VALUE_FLAGS.has(a)) i++;
      continue;
    }
    out.push(a);
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Subcommands                                                         */
/* ------------------------------------------------------------------ */

function printHelp() {
  const lines = [
    '',
    bold(`alpha-agent v${VERSION} — OpenClaw-style multi-provider personal AI agent`),
    '',
    bold('Usage:'),
    '  alphaa                       Start the interactive chat REPL',
    '  alphaa ask "<question>"      One-shot prompt (-p provider, -m model, -s session, --no-tools, --new)',
    '  alphaa configure             Interactive setup wizard (writes ~/.alpha-agent/config.json)',
    '  alphaa sessions              List all sessions',
    '  alphaa use <session>         Switch the active session',
    '  alphaa new [name]            Create and switch to a new session',
    '  alphaa rm <session>          Delete a session',
    '  alphaa rename <s> <new>      Rename a session',
    '  alphaa providers             Show available providers and default models',
    '  alphaa system "<prompt>"     Set the default system prompt',
    '  alphaa status                Show config path, provider, sessions and key status',
    '  alphaa serve                 Start the web UI (default port 3838)',
    '  alphaa env                   Show which API keys are set (values hidden)',
    '  alphaa help                  Show this help',
    '',
    bold('REPL commands:'),
    '  /new [name]   /use <session>   /list   /rm <session>   /rename <new>   /clear',
    '  /provider [id]   /model [id]   /system [text]   /tools on|off   /temperature <n>',
    '  /usage   /config   /session   /help   /exit',
    '',
    bold('Providers:'),
    ...providerTable().map(
      (p) =>
        `  ${cyan(p.id.padEnd(11))} ${p.name.padEnd(28)} default: ${yellow(p.defaultModel)}${
          p.needsKey ? '' : '  (key optional)'
        }`
    ),
    '',
    'Data lives in ~/.alpha-agent/ (config.json, sessions/, state.json).',
    '',
  ];
  console.log(lines.join('\n'));
}

async function ask(argv) {
  const config = loadConfig();
  const store = new SessionStore().init();

  const provider = flagValue(argv, ['-p', '--provider']) || config.provider;
  const model = flagValue(argv, ['-m', '--model']) || config.model;
  const sessionName = flagValue(argv, ['-s', '--session']);
  const noTools = flagBool(argv, ['--no-tools', '-n']);
  const newSession = flagBool(argv, ['--new']);

  const prompt = stripFlags(argv).join(' ').trim();
  if (!prompt) {
    console.error(red('No question given. Usage: alphaa ask "your question"'));
    process.exitCode = 1;
    return;
  }

  if (newSession) {
    store.setCurrent(store.create(sessionName || undefined).id);
  } else if (sessionName) {
    const found = store.find(sessionName);
    if (!found) {
      console.error(red(`Session "${sessionName}" not found. Use --new to create one.`));
      process.exitCode = 1;
      return;
    }
    store.use(found.id);
  }

  const agent = new Agent({
    store,
    config: { ...config, tools: noTools ? false : config.tools },
    providerId: provider,
    model,
  });

  console.log(dim(`→ ${agent.providerId}/${agent.model || PROVIDERS[provider]?.defaultModel}`));
  const renderer = createStreamRenderer();
  let spinner = startSpinner('thinking…');
  let sawToken = false;
  let usage = {};
  try {
    for await (const ev of agent.stream(prompt)) {
      if (ev.type === 'reasoning') {
        if (!sawToken) {
          stopSpinner(spinner);
          spinner = null;
          sawToken = true;
        }
        process.stdout.write(dim(ev.text));
      } else if (ev.type === 'text') {
        if (!sawToken) {
          stopSpinner(spinner);
          spinner = null;
          sawToken = true;
        }
        process.stdout.write(renderer.feed(ev.text));
      } else if (ev.type === 'tool') {
        if (!sawToken) {
          stopSpinner(spinner);
          spinner = null;
          sawToken = true;
        }
        console.log('');
        for (const tc of ev.toolCalls) {
          const name = tc.function?.name || '';
          console.log(`${dim('╭─')} ${yellow(`tool · ${name}`)} ${dim('─'.repeat(Math.max(8, 44 - name.length)))}`);
        }
      } else if (ev.type === 'tool_result') {
        console.log(dim(truncate(ev.result, 600)));
      } else if (ev.type === 'usage') {
        usage = ev.usage || usage;
      } else if (ev.type === 'result') {
        usage = ev.usage || usage;
      }
    }
    stopSpinner(spinner);
    const tail = renderer.flush();
    if (tail) process.stdout.write(tail);
    console.log('\n');
  } catch (err) {
    stopSpinner(spinner);
    const tail = renderer.flush();
    if (tail) process.stdout.write(tail);
    console.error(`\n${red(`Error: ${err.message}`)}`);
    process.exitCode = 1;
    return;
  }
  const total = (usage.promptTokens || 0) + (usage.completionTokens || 0);
  console.log(dim(`↑ ${fmtTokens(usage.promptTokens)} in · ${fmtTokens(usage.completionTokens)} out · ${fmtTokens(total)} total`));
}

function sessionLabel(s, currentId) {
  const mark = s.id === currentId ? green('●') : dim('○');
  const name = truncate(s.name, 30);
  const msgs = s.messages.length;
  const usage = s.usage?.promptTokens + s.usage?.completionTokens || 0;
  const when = new Date(s.updatedAt || s.createdAt).toLocaleString();
  return `  ${mark} ${cyan(s.id.slice(0, 8))}  ${bold(name.padEnd(31))} ${String(msgs).padStart(4)} msgs  ${String(usage).padStart(8)} tok  ${dim(when)}`;
}

async function listSessions() {
  const store = new SessionStore().init();
  const current = store.current();
  const list = store.list();
  if (!list.length) {
    console.log('No sessions yet.');
    return;
  }
  console.log(`\n${bold(list.length + ' sessions')} — current: ${green(current.name)}\n`);
  for (const s of list) console.log(sessionLabel(s, current.id));
  console.log('');
}

async function useSession(argv) {
  const name = argv[0];
  if (!name) {
    console.error(red('Usage: alphaa use <session-name|id>'));
    process.exitCode = 1;
    return;
  }
  const store = new SessionStore().init();
  const session = store.use(name);
  if (!session) {
    console.error(red(`Session "${name}" not found. See \`alphaa sessions\`.`));
    process.exitCode = 1;
    return;
  }
  console.log(green(`Switched to session "${session.name}" (${session.id.slice(0, 8)}).`));
}

async function newSession(argv) {
  const store = new SessionStore().init();
  const name = argv[0] || 'untitled';
  const session = store.create(name);
  store.setCurrent(session.id);
  console.log(green(`Created and switched to session "${session.name}" (${session.id.slice(0, 8)}).`));
}

async function removeSession(argv) {
  const name = argv[0];
  if (!name) {
    console.error(red('Usage: alphaa rm <session-name|id>'));
    process.exitCode = 1;
    return;
  }
  const store = new SessionStore().init();
  const removed = store.remove(name);
  if (!removed) {
    console.error(red(`Session "${name}" not found.`));
    process.exitCode = 1;
    return;
  }
  console.log(green(`Deleted session "${removed.name}".`));
}

async function renameSession(argv) {
  const [name, newName] = argv;
  if (!name || !newName) {
    console.error(red('Usage: alphaa rename <session> <new-name>'));
    process.exitCode = 1;
    return;
  }
  const store = new SessionStore().init();
  const session = store.rename(name, newName);
  if (!session) {
    console.error(red(`Session "${name}" not found.`));
    process.exitCode = 1;
    return;
  }
  console.log(green(`Renamed session to "${session.name}".`));
}

function printProviders() {
  console.log('');
  for (const p of providerTable()) {
    const key = p.env && process.env[p.env] ? green('key set') : red(p.needsKey ? 'no key' : 'key optional');
    console.log(
      `  ${cyan(p.id.padEnd(11))} ${p.name.padEnd(28)} ${yellow(p.defaultModel.padEnd(24))} ${key}`
    );
  }
  console.log('');
}

async function setSystemConfig(argv) {
  const text = argv.join(' ').trim();
  const config = readRawConfig();
  if (!text) {
    console.log(dim(config.system || '(default system prompt)'));
    return;
  }
  config.system = text;
  saveConfig(config);
  console.log(green('Default system prompt updated in ~/.alpha-agent/config.json.'));
}

async function printStatus() {
  const config = loadConfig();
  const store = new SessionStore().init();
  const current = store.current();
  const sessions = store.list();
  console.log('');
  console.log(`  Home:            ${homeDir()}`);
  console.log(`  Config:          ~/.alpha-agent/config.json`);
  console.log(`  Provider:        ${cyan(config.provider)}${dim(` (${PROVIDERS[config.provider]?.name})`)}`);
  console.log(`  Model:           ${yellow(config.model || PROVIDERS[config.provider]?.defaultModel)}`);
  console.log(`  Session:         ${green(current.name)} (${current.id.slice(0, 8)})`);
  console.log(`  Sessions:        ${sessions.length}`);
  console.log(`  Tools:           ${config.tools ? green('enabled') : red('disabled')}`);
  console.log(`  Temperature:     ${config.temperature}`);
  const keys = Object.values(PROVIDERS)
    .map((p) => p.env)
    .filter((k, i, a) => a.indexOf(k) === i);
  const set = keys.filter((k) => process.env[k]);
  console.log(`  API keys set:    ${set.length ? green(set.join(', ')) : red('none — run `alphaa configure`')}`);
  console.log('');
}

function printEnv() {
  console.log('');
  for (const p of providerTable()) {
    const names = [p.env];
    const set = names.some((n) => process.env[n]);
    console.log(`  ${cyan(p.id.padEnd(11))} ${(p.env || '').padEnd(24)} ${set ? green('set') : red('not set')}`);
  }
  console.log('');
}

/* ------------------------------------------------------------------ */
/* Interactive REPL                                                    */
/* ------------------------------------------------------------------ */

const COMMANDS = [
  'new',
  'use',
  'list',
  'rm',
  'rename',
  'clear',
  'provider',
  'model',
  'system',
  'tools',
  'temperature',
  'usage',
  'config',
  'session',
  'help',
  'exit',
  'quit',
];

function compactArgs(args) {
  try {
    return JSON.stringify(args);
  } catch {
    return String(args);
  }
}

async function repl(argv = []) {
  const config = loadConfig();
  const flagProvider = flagValue(argv, ['-p', '--provider']);
  const flagModel = flagValue(argv, ['-m', '--model']);
  const store = new SessionStore().init();
  let agent = new Agent({
    store,
    config,
    providerId: flagProvider || undefined,
    model: flagModel || undefined,
  });

  const persist = (patch) => {
    saveConfig({ ...readRawConfig(), ...patch });
    config.provider = patch.provider || config.provider;
    config.model = patch.model || config.model;
    config.system = patch.system ?? config.system;
  };

  const banner = () => {
    const sess = store.current().name;
    const model = agent.model || PROVIDERS[agent.providerId]?.defaultModel;
    const bar = dim('─'.repeat(46));
    console.log('');
    console.log(bar);
    console.log(`${dim('│')}  ${bold(`alpha-agent v${VERSION}`)}  ${dim('· OpenClaw-style personal AI agent')}`);
    console.log(
      `${dim('│')}  ${green(`● ${sess}`)}  ${cyan(agent.providerId)}/${yellow(model)}  ${dim('Ctrl-C stop · /exit quit')}`
    );
    console.log(bar);
    console.log('');
  };

  const promptStr = () => {
    const sess = truncate(store.current()?.name ?? 'main', 14);
    const model = agent.model || PROVIDERS[agent.providerId]?.defaultModel;
    return `${dim('alpha')} ${cyan(`[${sess}]`)} ${yellow(`${agent.providerId}/${model}`)} ${green('❯')} `;
  };

  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: process.stdin.isTTY,
    completer: makeCompleter(store, () => agent),
  });

  let streaming = false;
  let controller = null;

  const stopStream = () => controller?.abort();

  const finish = () => {
    process.exit(0);
  };

  process.on('SIGINT', () => {
    if (streaming) {
      stopStream();
      process.stdout.write('\n');
    } else {
      finish();
    }
  });

  const handleCommand = (line) => {
    const [cmd, ...rest] = line.slice(1).trim().split(/\s+/);
    const arg = rest.join(' ');
    switch (cmd) {
      case 'help': {
        console.log(
          [
            '',
            bold('Commands:'),
            '  /new [name]          new session',
            '  /use <session>       switch session',
            '  /list                list sessions',
            '  /rm <session>        delete session',
            '  /rename <new>        rename current session',
            '  /clear               clear current session',
            '  /provider [id]       show or switch provider',
            '  /model [id]          show or switch model',
            '  /system [text]       show or set system prompt',
            '  /tools on|off        toggle tools',
            '  /temperature <n>     set temperature (0–2)',
            '  /usage               token usage of current session',
            '  /config              show config path & current settings',
            '  /session             show current session info',
            '  /help                this help',
            '  /exit                quit',
            '',
            dim('Tip: end a line with \\ or an open ``` to continue typing on the next line.'),
            '',
          ].join('\n')
        );
        break;
      }
      case 'exit':
      case 'quit':
        finish();
        return true;
      case 'new': {
        const s = store.create(arg || 'untitled');
        store.setCurrent(s.id);
        console.log(green(`New session "${s.name}" (${s.id.slice(0, 8)}).`));
        break;
      }
      case 'use': {
        const s = store.use(arg);
        if (!s) console.error(red(`Session "${arg}" not found.`));
        else console.log(green(`Switched to "${s.name}" (${s.id.slice(0, 8)}).`));
        break;
      }
      case 'list':
        console.log('');
        for (const s of store.list()) console.log(sessionLabel(s, store.current().id));
        console.log('');
        break;
      case 'rm': {
        const s = store.remove(arg);
        if (!s) console.error(red(`Session "${arg}" not found.`));
        else console.log(green(`Deleted "${s.name}".`));
        break;
      }
      case 'rename': {
        const s = store.rename(store.current().id, arg);
        if (s) console.log(green(`Renamed to "${s.name}".`));
        break;
      }
      case 'clear': {
        store.clear(store.current().id);
        console.log(green('Session cleared.'));
        break;
      }
      case 'provider': {
        if (!arg) {
          console.log(`Current provider: ${cyan(agent.providerId)} (${PROVIDERS[agent.providerId]?.name})`);
          console.log(`Available: ${providerIds().join(', ')}`);
          break;
        }
        if (!PROVIDERS[arg]) {
          console.error(red(`Unknown provider "${arg}". Available: ${providerIds().join(', ')}`));
          break;
        }
        agent.setProvider(arg, PROVIDERS[arg].defaultModel);
        persist({ provider: arg, model: PROVIDERS[arg].defaultModel });
        console.log(green(`Provider → ${arg} (${PROVIDERS[arg].defaultModel}).`));
        break;
      }
      case 'model': {
        if (!arg) {
          console.log(`Current model: ${yellow(agent.model || PROVIDERS[agent.providerId]?.defaultModel)}`);
          console.log(dim(`  ${agent.providerId} defaults: ${(PROVIDERS[agent.providerId]?.models || []).join(', ')}`));
          break;
        }
        agent.setModel(arg);
        persist({ model: arg });
        console.log(green(`Model → ${arg}.`));
        break;
      }
      case 'system': {
        if (!arg) {
          console.log(dim(agent.system || '(none)'));
          break;
        }
        agent.setSystem(arg);
        persist({ system: arg });
        console.log(green('System prompt updated for future turns.'));
        break;
      }
      case 'tools': {
        const v = arg.toLowerCase();
        if (v === 'on') {
          agent.toolsEnabled = true;
          console.log(green('Tools enabled.'));
        } else if (v === 'off') {
          agent.toolsEnabled = false;
          console.log(yellow('Tools disabled.'));
        } else {
          console.log(`Tools: ${agent.toolsEnabled ? green('enabled') : red('disabled')}`);
        }
        break;
      }
      case 'temperature': {
        const t = parseFloat(arg);
        if (Number.isNaN(t) || t < 0 || t > 2) {
          console.error(red('Temperature must be a number between 0 and 2.'));
          break;
        }
        agent.config.temperature = t;
        persist({ temperature: t });
        console.log(green(`Temperature → ${t}.`));
        break;
      }
      case 'usage': {
        const s = store.current();
        console.log(`Usage for "${s.name}": ${fmtTokens(s.usage?.promptTokens)} in · ${fmtTokens(s.usage?.completionTokens)} out`);
        break;
      }
      case 'config':
        console.log(`  Config file: ${dim('~/.alpha-agent/config.json')}`);
        console.log(`  provider=${cyan(agent.providerId)} model=${yellow(agent.model || '-' )} temperature=${agent.config.temperature} tools=${agent.toolsEnabled}`);
        break;
      case 'session':
        console.log(sessionLabel(store.current(), store.current().id));
        break;
      default:
        console.error(red(`Unknown command "/${cmd}". Type /help.`));
    }
    return false;
  };

  const handleChat = async (line) => {
    streaming = true;
    controller = new AbortController();
    const renderer = createStreamRenderer();
    let spinner = startSpinner('thinking…');
    try {
      for await (const ev of agent.stream(line, { signal: controller.signal })) {
        if (ev.type === 'reasoning') {
          stopSpinner(spinner);
          spinner = null;
          process.stdout.write(dim(ev.text));
        } else if (ev.type === 'text') {
          stopSpinner(spinner);
          spinner = null;
          process.stdout.write(renderer.feed(ev.text));
        } else if (ev.type === 'tool') {
          stopSpinner(spinner);
          spinner = null;
          console.log('');
          for (const tc of ev.toolCalls) {
            const name = tc.function?.name || '';
            const args = tc.function?.arguments ? ` ${dim(compactArgs(tc.function.arguments).slice(0, 120))}` : '';
            console.log(`${dim('╭─')} ${yellow(`tool · ${name}`)}${args} ${dim('─'.repeat(Math.max(4, 40 - name.length - args.length)))}`);
          }
        } else if (ev.type === 'tool_result') {
          console.log(dim(truncate(ev.result, 600)));
          console.log(dim('╰' + '─'.repeat(46)));
        }
      }
      stopSpinner(spinner);
      const tail = renderer.flush();
      if (tail) process.stdout.write(tail);
      if (tail) process.stdout.write('\n');
      console.log('\n');
    } catch (err) {
      stopSpinner(spinner);
      const tail = renderer.flush();
      if (tail) process.stdout.write(tail + '\n');
      if (err.name === 'AbortError' || controller.signal.aborted) {
        console.log(red('[stopped]'));
      } else {
        console.error(`\n${red(`Error: ${err.message}`)}`);
      }
    } finally {
      streaming = false;
      controller = null;
    }
  };

  // ---- multi-line input: continue when line ends with "\" or has an open ``` fence
  const needsContinuation = (text) => {
    const fenceCount = (text.match(/```/g) || []).length;
    if (fenceCount % 2 === 1) return true;
    return /\\\s*$/.test(text);
  };

  let pending = '';

  banner();
  rl.setPrompt(promptStr());
  rl.prompt();

  rl.on('line', async (raw) => {
    if (pending) pending += '\n' + raw;
    else pending = raw;

    if (needsContinuation(pending)) {
      console.log(dim('  … continuing (enter a blank line to send)'));
      rl.setPrompt('  … ');
      rl.prompt();
      return;
    }

    const line = pending.trim();
    pending = '';
    rl.setPrompt(promptStr());

    if (!line) {
      rl.prompt();
      return;
    }
    if (line.startsWith('/')) {
      const exit = handleCommand(line);
      rl.setPrompt(promptStr());
      rl.prompt();
      if (exit) rl.close();
      return;
    }
    rl.pause();
    await handleChat(line);
    rl.resume();
    rl.prompt();
  });
}

/** Tab-completion for slash commands, providers, models and sessions. */
function makeCompleter(store, getAgent) {
  return (line) => {
    const trimmed = line.trimStart();
    if (!trimmed.startsWith('/')) return [[], line];
    const tokens = trimmed.split(/\s+/);
    const head = tokens[0].slice(1);
    const last = tokens[tokens.length - 1] || '';
    const hasArg = tokens.length > 1;

    let cands = [];
    if (!hasArg) {
      cands = COMMANDS.filter((c) => c.startsWith(head)).map((c) => `/${c} `);
    } else if (head === 'provider') {
      cands = providerIds().filter((p) => p.startsWith(last));
    } else if (head === 'model') {
      const agent = getAgent();
      cands = (PROVIDERS[agent.providerId]?.models || []).filter((m) => m.startsWith(last));
    } else if (head === 'use' || head === 'rm' || head === 'rename' || head === 'new') {
      cands = store
        .list()
        .map((s) => s.name)
        .filter((n) => n.startsWith(last));
    }
    if (cands.length === 1) cands[0] = cands[0] + ' ';
    return [cands, line];
  };
}

