async function configure() {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  const q = (prompt) => new Promise((resolve) => rl.question(prompt, resolve));

  console.log('');
  console.log(bold('alpha-agent configuration wizard'));
  console.log(dim('  This writes ~/.alpha-agent/config.json. API keys go to ~/.alpha-agent/.env.'));
  console.log('');
  console.log(dim('  Providers:'));
  for (const p of providerTable()) {
    console.log(`    ${cyan(p.id.padEnd(11))} ${p.name}${p.needsKey ? '' : dim(' (key optional)')}`);
  }
  console.log('');

  let provider = (await q('Provider (default openai) > ')).trim() || 'openai';
  while (!PROVIDERS[provider]) {
    console.error(red(`  Unknown provider "${provider}".`));
    provider = (await q('Provider > ')).trim();
  }
  const spec = PROVIDERS[provider];

  const model = (await q(`Model (default ${spec.defaultModel}) > `)).trim() || spec.defaultModel;

  let key = '';
  if (spec.requiresKey) {
    key = (await q(`${spec.env} API key (leave blank to skip) > `)).trim();
  } else {
    key = (await q(`${spec.env} API key (optional, leave blank to skip) > `)).trim();
  }

  const toolsRaw = (await q('Enable tools (shell / files / web)? [Y/n] > ')).trim().toLowerCase();
  const tools = toolsRaw !== 'n' && toolsRaw !== 'no';

  const system = (await q('System prompt (blank for default) > ')).trim();
  rl.close();

  const config = readRawConfig();
  config.provider = provider;
  config.model = model;
  config.tools = tools;
  if (system) config.system = system;
  saveConfig(config);

  if (key) {
    ensureHome();
    const envFile = path.join(homeDir(), '.env');
    const existing = fs.existsSync(envFile) ? fs.readFileSync(envFile, 'utf8') : '';
    const line = `${spec.env}=${key}`;
    const next = existing.includes(`${spec.env}=`)
      ? existing.replace(new RegExp(`^${spec.env}=.*$`, 'm'), line)
      : `${existing.trimEnd()}\n${line}\n`;
    fs.writeFileSync(envFile, next);
  }

  console.log('');
  console.log(green('Done!'));
  console.log(`  provider = ${provider}`);
  console.log(`  model    = ${model}`);
  console.log(`  tools    = ${tools ? 'on' : 'off'}`);
  if (key) console.log(`  key      = written to ~/.alpha-agent/.env`);
  console.log('');
  console.log(dim('  Try: alphaa'));
}

