import http from 'node:http';
import { readFileSync } from 'node:fs';
import { Agent } from './agent.js';
import { SessionStore } from './session.js';
import { PROVIDERS } from './constants.js';

const UI_PATH = new URL('./ui/index.html', import.meta.url);

function readUI() {
  try {
    return readFileSync(UI_PATH, 'utf8');
  } catch {
    return null;
  }
}

const HOST = process.env.ALPHA_AGENT_WEB_HOST || '127.0.0.1';

function json(res, status, body) {
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Cache-Control': 'no-store',
  });
  res.end(JSON.stringify(body));
}

function readBody(req) {
  return new Promise((resolve) => {
    let data = '';
    req.on('data', (c) => (data += c));
    req.on('end', () => {
      try {
        resolve(JSON.parse(data || '{}'));
      } catch {
        resolve({});
      }
    });
  });
}

function sse(res) {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive',
    'Access-Control-Allow-Origin': '*',
  });
  res.write(': connected\n\n');
  return (event, data) => res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function snapshot(store) {
  const current = store.current();
  const sessions = store.list().map((s) => ({
    id: s.id,
    name: s.name,
    messages: s.messages.length,
    tokens: (s.usage?.promptTokens || 0) + (s.usage?.completionTokens || 0),
    updatedAt: s.updatedAt,
  }));
  return {
    currentSessionId: current.id,
    currentSessionName: current.name,
    sessions,
    providers: Object.values(PROVIDERS).map((p) => ({
      id: p.id,
      name: p.name,
      defaultModel: p.defaultModel,
      models: p.models || [],
      needsKey: p.requiresKey,
      keySet: !p.requiresKey || Boolean(process.env[p.env]),
    })),
  };
}

export async function startServer({ config, port }) {
  const store = new SessionStore().init();
  const agent = new Agent({ store, config });
  let currentAgent = agent;

  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, `http://${req.headers.host}`);

    if (req.method === 'GET' && url.pathname === '/') {
      const html = readUI();
      if (html === null) {
        json(res, 500, { error: 'ui/index.html missing — reinstall the package or restore src/ui/index.html' });
        return;
      }
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(html);
      return;
    }

    if (req.method === 'GET' && url.pathname === '/api/state') {
      json(res, 200, {
        ...snapshot(store),
        config: {
          provider: currentAgent.providerId,
          model: currentAgent.model || PROVIDERS[currentAgent.providerId]?.defaultModel,
          tools: currentAgent.toolsEnabled,
          temperature: currentAgent.config.temperature,
        },
      });
      return;
    }

    if (req.method === 'POST' && url.pathname === '/api/session/new') {
      const body = await readBody(req);
      const s = store.create(body.name || 'untitled');
      store.setCurrent(s.id);
      json(res, 200, snapshot(store));
      return;
    }

    if (req.method === 'POST' && url.pathname === '/api/session/use') {
      const body = await readBody(req);
      const s = store.use(body.id || body.name);
      json(res, 200, snapshot(store));
      return;
    }

    if (req.method === 'POST' && url.pathname === '/api/session/delete') {
      const body = await readBody(req);
      store.remove(body.id);
      json(res, 200, snapshot(store));
      return;
    }

    if (req.method === 'POST' && url.pathname === '/api/chat') {
      const body = await readBody(req);
      const message = String(body.message || '').trim();
      if (!message) {
        json(res, 400, { error: 'message is required' });
        return;
      }

      const emit = sse(res);
      let chatAgent = currentAgent;
      if (body.provider || body.model) {
        chatAgent = new Agent({
          store,
          config: { ...currentAgent.config },
          providerId: body.provider || currentAgent.providerId,
          model: body.model || currentAgent.model,
        });
      }

      try {
        for await (const ev of chatAgent.stream(message)) {
          if (ev.type === 'text') emit('text', { text: ev.text });
          else if (ev.type === 'tool_result') emit('tool', { name: ev.name, result: ev.result });
          else if (ev.type === 'result') emit('result', { usage: ev.usage });
        }
        emit('done', {});
      } catch (err) {
        emit('error', { message: err.message });
      } finally {
        res.end();
      }
      return;
    }

    if (req.method === 'POST' && url.pathname === '/api/config') {
      const body = await readBody(req);
      if (body.provider && PROVIDERS[body.provider]) {
        currentAgent.setProvider(body.provider, body.model || PROVIDERS[body.provider].defaultModel);
      } else if (body.model) {
        currentAgent.setModel(body.model);
      }
      if (body.tools !== undefined) currentAgent.toolsEnabled = !!body.tools;
      json(res, 200, snapshot(store));
      return;
    }

    json(res, 404, { error: 'not found' });
  });

  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, HOST, resolve);
  });

  const shown = `http://${HOST}:${port}`;
  console.log(`alpha-agent web UI running at ${shown}`);
  return server;
}

import { PROVIDERS } from '../constants.js';
import { OpenAICompatibleProvider } from './openai-compatible.js';
import { AnthropicProvider } from './anthropic.js';
import { GeminiProvider } from './gemini.js';
import { ProviderError } from './base.js';

const KINDS = {
  openai: OpenAICompatibleProvider,
  anthropic: AnthropicProvider,
  gemini: GeminiProvider,
};

export { PROVIDERS };
export { Provider, ProviderError } from './base.js';
export { OpenAICompatibleProvider } from './openai-compatible.js';
export { AnthropicProvider } from './anthropic.js';
export { GeminiProvider } from './gemini.js';

/**
 * Instantiate a provider by id.
 * @param {string} providerId e.g. "openai", "claude", "gemini", ...
 * @param {object} [options] {apiKey, baseURL, headers, requestTimeoutMs, fetch}
 */
export function createProvider(providerId, options = {}) {
  const spec = PROVIDERS[providerId];
  if (!spec) {
    throw new ProviderError(
      `Unknown provider "${providerId}". Available: ${Object.keys(PROVIDERS).join(', ')}`
    );
  }
  const Klass = KINDS[spec.kind];
  return new Klass(spec, options);
}

/** All provider ids. */
export function providerIds() {
  return Object.keys(PROVIDERS);
}

/** Human-readable table of providers and their default model. */
export function providerTable() {
  return Object.values(PROVIDERS).map((p) => ({
    id: p.id,
    name: p.name,
    kind: p.kind,
    defaultModel: p.defaultModel,
    needsKey: p.requiresKey,
    env: p.env,
  }));
}

export default createProvider;
